=Here is the approved book plan from the Creative Director:

{{ JSON.stringify($json.output) }}

Write the final gpt-image-1 prompts: one cover prompt and one prompt per page, following your style rules exactly.

=Review these image prompts before we spend money generating images:

{{ JSON.stringify($json.output) }}

Check every prompt against your checklist, fix any problems directly, and return the FINAL corrected JSON (same structure).

parameters.jsCode:
// รับผล JSON สุดท้ายจาก Art Director QA แล้วแตกเป็นรายการภาพ: ปก 1 + หน้าระบายสี 4
const out = $input.first().json.output;
const stamp = $now.toFormat('yyyyLLdd_HHmm');
const slug = (out.theme_slug || out.theme || 'Theme').replace(/[^A-Za-z0-9]+/g, '');
const safeTitle = (out.book_title || 'Coloring Book').replace(/[^A-Za-z0-9 '\-]+/g, '').trim();
const meta = {
  theme: out.theme,
  theme_slug: slug,
  book_title: out.book_title,
  folder_name: 'ColoringBook_' + slug + '_' + stamp,
  pdf_name: safeTitle + '.pdf',
};

const items = [{ json: { ...meta, index: 0, kind: 'cover', filename: 'cover.jpg', prompt: out.cover_prompt } }];
(out.page_prompts || []).forEach((p, i) => {
  items.push({ json: { ...meta, index: i + 1, kind: 'page', filename: 'page_' + (i + 1) + '.jpg', prompt: p } });
});
return items;

